        if (tradesArray.is_none()) {
            let mut limit: i64 = self.safe_integer_k(self.options.clone(), "tradesLimit", &[Value::Int(1000)]).as_i64().unwrap_or(1000);
            tradesArray = Some(ArrayCache::new(limit));
        }
        tradesArray.append(trade);
